import{_ as s,o as e,c as a,ao as t}from"./chunks/framework.Irjqg1aB.js";const g=JSON.parse('{"title":"Topologies, grids, and fields","description":"","frontmatter":{},"headers":[],"relativePath":"guide/concepts.md","filePath":"guide/concepts.md","lastUpdated":null}'),o={name:"guide/concepts.md"};function n(d,i,l,h,r,c){return e(),a("div",null,[...i[0]||(i[0]=[t(`<h1 id="Topologies,-grids,-and-fields" tabindex="-1">Topologies, grids, and fields <a class="header-anchor" href="#Topologies,-grids,-and-fields" aria-label="Permalink to &quot;Topologies, grids, and fields {#Topologies,-grids,-and-fields}&quot;">​</a></h1><p>The package separates process layout, local sizing, and array storage:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Value</th><th style="text-align:right;">Responsibility</th><th style="text-align:right;">Constructor</th></tr></thead><tbody><tr><td style="text-align:right;"><code>Topology</code></td><td style="text-align:right;">Cartesian communicator, process dimensions, neighbors</td><td style="text-align:right;"><code>topology((0, 0))</code></td></tr><tr><td style="text-align:right;"><code>Grid</code></td><td style="text-align:right;">Local array size, coordinate metadata, exchange cache</td><td style="text-align:right;"><code>grid(t, (34, 34))</code></td></tr><tr><td style="text-align:right;"><code>Field</code></td><td style="text-align:right;">Existing array and halo widths</td><td style="text-align:right;"><code>field(A; halowidths=(1, 1))</code></td></tr></tbody></table><p>Both the constructor functions and the type names are exported.</p><h2 id="Process-topology" tabindex="-1">Process topology <a class="header-anchor" href="#Process-topology" aria-label="Permalink to &quot;Process topology {#Process-topology}&quot;">​</a></h2><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> topology</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">((</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">); periods</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span></code></pre></div><p>Topology dimensions count MPI processes. A zero lets MPI choose that dimension; fixed dimensions must be compatible with the communicator size. Only two and three dimensions are supported. Every constructor call creates a fresh Cartesian communicator. <code>t.rank</code> and <code>t.coords</code> are zero-based; use <code>t.rank</code> when selecting a root inside <code>t.comm</code>, since rank reordering is enabled by default.</p><p><code>t.neighbors[d]</code> contains the lower and upper neighbors along dimension <code>d</code>. Use <code>has_neighbor(rank)</code> to distinguish a real rank from <code>MPI.PROC_NULL</code>. At a nonperiodic domain edge, the missing neighbor does not supply boundary data; the application must impose its physical boundary conditions.</p><h2 id="Local-sizes-include-halos" tabindex="-1">Local sizes include halos <a class="header-anchor" href="#Local-sizes-include-halos" aria-label="Permalink to &quot;Local sizes include halos {#Local-sizes-include-halos}&quot;">​</a></h2><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">g </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> grid</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(t, (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">34</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">34</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">A </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> zeros</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(g</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">nlocal)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">f </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> field</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(A; halowidths</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span></code></pre></div><p>The field wraps <code>A</code> without copying it. Access values through <code>f.data</code> or <code>A</code>. <code>Field</code> is a wrapper, not an <code>AbstractArray</code> with its own indexing interface. Its interior is <code>A[2:33, 2:33]</code>. In general, dimension <code>d</code> has interior indices <code>h+1:size(A,d)-h</code>, where <code>h = halowidths(f)[d]</code>.</p><p>Field construction requires a bits element type, positive halo widths, and <code>2h &lt;= size(A,d)</code>. Choose local sizes with enough interior cells for the intended stencil; constructor validation alone does not establish that a numerical stencil is meaningful.</p><p>All fields in an exchange must match <code>g.nlocal</code> and the grid dimensionality. Fields may have different element types or halo widths. Use distinct backing arrays: duplicate array objects are rejected, but overlapping views are not comprehensively checked for aliasing.</p><h2 id="Multiple-grids" tabindex="-1">Multiple grids <a class="header-anchor" href="#Multiple-grids" aria-label="Permalink to &quot;Multiple grids {#Multiple-grids}&quot;">​</a></h2><p>A grid owns its cache, so sequential use of multiple grids needs no global reset. For independently overlapping exchanges, construct a separate topology for each grid. Grids built on the same topology share its communicator, and exchange messages use the same tag; separate caches alone do not isolate those messages.</p><p><code>origin</code>, <code>origin_on_vertex</code>, and <code>centered</code> are coordinate metadata on <code>Grid</code>. They do not generate coordinates or change halo widths. See <a href="/HaloArrays.jl/dev/api#grid">the API</a> for the parity rules used when constructing centered grids.</p>`,16)])])}const k=s(o,[["render",n]]);export{g as __pageData,k as default};
